$s =~ s/(        if\(cleanup==0 \&\& fault\.\*\.primary_error)/        if(cleanup==1 \&\& fault.*.cleanup_error!=0){let error:i32=fault.*.cleanup_error;fault.*.cleanup_error=0;fault.*.injected=fault.*.injected+1;return error as i64;}\n$1/;
